#include "../src/telemetry.hpp"
#include <iostream>
using namespace arc;
static uint64_t cpuTicks(){FILETIME c,e,k,u;GetProcessTimes(GetCurrentProcess(),&c,&e,&k,&u);return (uint64_t(k.dwHighDateTime)<<32)+k.dwLowDateTime+(uint64_t(u.dwHighDateTime)<<32)+u.dwLowDateTime;}
int main(){auto start=cpuTicks();std::this_thread::sleep_for(std::chrono::seconds(6));auto idle=cpuTicks()-start;Settings config;for(auto& m:config.metrics){m.enabled=false;m.period=1000;}for(auto id:{Metric::Cpu,Metric::SelfCpu,Metric::Ram,Metric::CpuPower})config.metrics[index(id)].enabled=true;Snapshot data;start=cpuTicks();{Telemetry reader(config,LUID{},{});std::this_thread::sleep_for(std::chrono::seconds(6));data=reader.snapshot();}auto active=cpuTicks()-start;std::cout<<"backend only, six seconds each, no UI or game\n"<<"idle CPU ms="<<idle/10000.0<<" active CPU ms="<<active/10000.0<<" active machine CPU percent="<<double(active)/6e5/GetActiveProcessorCount(ALL_PROCESSOR_GROUPS)<<"\nwakes="<<data.wakes<<" max query ms="<<data.maxWorkMs<<" GPU engine queries="<<data.engineQueries<<" GPU memory queries="<<data.memoryQueries<<"\n";if(data.metrics[index(Metric::CpuPower)].value)std::cout<<"package watts="<<*data.metrics[index(Metric::CpuPower)].value<<"\n";return 0;}
